INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id) SELECT mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) global_rank FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category,player_id ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) personal_rank FROM (SELECT r.mode,'won' category,r.player_id,r.id run_id,r.equity_cents value,COALESCE(r.gain_cents,0) gain_cents,r.trades,r.submitted_at,r.id tie_id FROM sf_runs r JOIN sf_players p ON p.id=r.player_id JOIN sf_leaderboard_editions e ON e.edition=r.edition AND e.mode=r.mode WHERE r.hidden=0 AND p.banned=0 AND p.nickname IS NOT NULL AND r.outcome='won' )) WHERE personal_rank=1) WHERE global_rank<=100;
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id) SELECT mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) global_rank FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category,player_id ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) personal_rank FROM (SELECT r.mode,'financing' category,r.player_id,r.id run_id,CAST(json_extract(r.margin_summary,'$.totalBorrowedCents') AS INTEGER) value,COALESCE(r.gain_cents,0) gain_cents,r.trades,r.submitted_at,r.id tie_id FROM sf_runs r JOIN sf_players p ON p.id=r.player_id JOIN sf_leaderboard_editions e ON e.edition=r.edition AND e.mode=r.mode WHERE r.hidden=0 AND p.banned=0 AND p.nickname IS NOT NULL AND json_extract(r.margin_summary,'$.totalBorrowedCents')>0 )) WHERE personal_rank=1) WHERE global_rank<=100;
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id) SELECT mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) global_rank FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category,player_id ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) personal_rank FROM (SELECT r.mode,'gain' category,r.player_id,r.id run_id,r.gain_cents value,COALESCE(r.gain_cents,0) gain_cents,r.trades,r.submitted_at,r.id tie_id FROM sf_runs r JOIN sf_players p ON p.id=r.player_id JOIN sf_leaderboard_editions e ON e.edition=r.edition AND e.mode=r.mode WHERE r.hidden=0 AND p.banned=0 AND p.nickname IS NOT NULL AND r.gain_cents>0 )) WHERE personal_rank=1) WHERE global_rank<=100;
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id) SELECT mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) global_rank FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category,player_id ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) personal_rank FROM (SELECT 'life' mode,'reincarnation' category,p.id player_id,NULL run_id,p.life_completed_count value,0 gain_cents,0 trades,p.life_last_completed_at submitted_at,p.id tie_id FROM sf_players p WHERE p.banned=0 AND p.nickname IS NOT NULL AND p.life_completed_count>0 )) WHERE personal_rank=1) WHERE global_rank<=100;
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id) SELECT mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) global_rank FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY mode,category,player_id ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id) personal_rank FROM (SELECT 'free' mode,'reincarnation' category,p.id player_id,NULL run_id,p.free_completed_count value,0 gain_cents,0 trades,p.free_last_completed_at submitted_at,p.id tie_id FROM sf_players p WHERE p.banned=0 AND p.nickname IS NOT NULL AND p.free_completed_count>0 )) WHERE personal_rank=1) WHERE global_rank<=100;
CREATE TRIGGER sf_top100_run_insert AFTER INSERT ON sf_runs BEGIN
UPDATE sf_runs SET board_before=(SELECT COALESCE(json_group_array(json_object('category',a.category,'runId',a.run_id,'value',a.value,'rank',1+(SELECT COUNT(*) FROM sf_leaderboard_top100 b WHERE b.mode=a.mode AND b.category=a.category AND ((b.value>a.value) OR (b.value=a.value AND b.gain_cents>a.gain_cents) OR (b.value=a.value AND b.gain_cents=a.gain_cents AND b.trades<a.trades) OR (b.value=a.value AND b.gain_cents=a.gain_cents AND b.trades=a.trades AND b.submitted_at<a.submitted_at) OR (b.value=a.value AND b.gain_cents=a.gain_cents AND b.trades=a.trades AND b.submitted_at=a.submitted_at AND b.tie_id<a.tie_id))))), '[]') FROM sf_leaderboard_top100 a WHERE a.player_id=NEW.player_id AND a.mode=NEW.mode AND a.category<>'reincarnation') WHERE id=NEW.id;
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id)
 SELECT c.mode,c.category,c.player_id,c.run_id,c.value,c.gain_cents,c.trades,c.submitted_at,c.tie_id FROM (SELECT r.mode,'won' category,r.player_id,r.id run_id,r.equity_cents value,COALESCE(r.gain_cents,0) gain_cents,r.trades,r.submitted_at,r.id tie_id FROM sf_runs r JOIN sf_players p ON p.id=r.player_id JOIN sf_leaderboard_editions e ON e.edition=r.edition AND e.mode=r.mode WHERE r.hidden=0 AND p.banned=0 AND p.nickname IS NOT NULL AND r.outcome='won' AND r.id=NEW.id) c
 WHERE (EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id AND ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id)))
 OR (NOT EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id)
 AND ((SELECT COUNT(*) FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category)<100
 OR EXISTS(SELECT 1 FROM (SELECT * FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category ORDER BY value,gain_cents,trades DESC,submitted_at DESC,tie_id DESC LIMIT 1) b WHERE ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id))))))
 ON CONFLICT(mode,category,player_id) DO UPDATE SET run_id=excluded.run_id,value=excluded.value,gain_cents=excluded.gain_cents,trades=excluded.trades,submitted_at=excluded.submitted_at,tie_id=excluded.tie_id;
DELETE FROM sf_leaderboard_top100 WHERE mode=NEW.mode AND category='won' AND player_id IN (SELECT player_id FROM sf_leaderboard_top100 WHERE mode=NEW.mode AND category='won' ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id LIMIT -1 OFFSET 100);
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id)
 SELECT c.mode,c.category,c.player_id,c.run_id,c.value,c.gain_cents,c.trades,c.submitted_at,c.tie_id FROM (SELECT r.mode,'financing' category,r.player_id,r.id run_id,CAST(json_extract(r.margin_summary,'$.totalBorrowedCents') AS INTEGER) value,COALESCE(r.gain_cents,0) gain_cents,r.trades,r.submitted_at,r.id tie_id FROM sf_runs r JOIN sf_players p ON p.id=r.player_id JOIN sf_leaderboard_editions e ON e.edition=r.edition AND e.mode=r.mode WHERE r.hidden=0 AND p.banned=0 AND p.nickname IS NOT NULL AND json_extract(r.margin_summary,'$.totalBorrowedCents')>0 AND r.id=NEW.id) c
 WHERE (EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id AND ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id)))
 OR (NOT EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id)
 AND ((SELECT COUNT(*) FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category)<100
 OR EXISTS(SELECT 1 FROM (SELECT * FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category ORDER BY value,gain_cents,trades DESC,submitted_at DESC,tie_id DESC LIMIT 1) b WHERE ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id))))))
 ON CONFLICT(mode,category,player_id) DO UPDATE SET run_id=excluded.run_id,value=excluded.value,gain_cents=excluded.gain_cents,trades=excluded.trades,submitted_at=excluded.submitted_at,tie_id=excluded.tie_id;
DELETE FROM sf_leaderboard_top100 WHERE mode=NEW.mode AND category='financing' AND player_id IN (SELECT player_id FROM sf_leaderboard_top100 WHERE mode=NEW.mode AND category='financing' ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id LIMIT -1 OFFSET 100);
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id)
 SELECT c.mode,c.category,c.player_id,c.run_id,c.value,c.gain_cents,c.trades,c.submitted_at,c.tie_id FROM (SELECT r.mode,'gain' category,r.player_id,r.id run_id,r.gain_cents value,COALESCE(r.gain_cents,0) gain_cents,r.trades,r.submitted_at,r.id tie_id FROM sf_runs r JOIN sf_players p ON p.id=r.player_id JOIN sf_leaderboard_editions e ON e.edition=r.edition AND e.mode=r.mode WHERE r.hidden=0 AND p.banned=0 AND p.nickname IS NOT NULL AND r.gain_cents>0 AND r.id=NEW.id) c
 WHERE (EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id AND ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id)))
 OR (NOT EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id)
 AND ((SELECT COUNT(*) FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category)<100
 OR EXISTS(SELECT 1 FROM (SELECT * FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category ORDER BY value,gain_cents,trades DESC,submitted_at DESC,tie_id DESC LIMIT 1) b WHERE ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id))))))
 ON CONFLICT(mode,category,player_id) DO UPDATE SET run_id=excluded.run_id,value=excluded.value,gain_cents=excluded.gain_cents,trades=excluded.trades,submitted_at=excluded.submitted_at,tie_id=excluded.tie_id;
DELETE FROM sf_leaderboard_top100 WHERE mode=NEW.mode AND category='gain' AND player_id IN (SELECT player_id FROM sf_leaderboard_top100 WHERE mode=NEW.mode AND category='gain' ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id LIMIT -1 OFFSET 100);
