CREATE TRIGGER sf_top100_completion_insert AFTER INSERT ON sf_life_completions BEGIN
UPDATE sf_life_completions SET board_before=(SELECT COALESCE(json_group_array(json_object('category',a.category,'runId',a.run_id,'value',a.value,'rank',1+(SELECT COUNT(*) FROM sf_leaderboard_top100 b WHERE b.mode=a.mode AND b.category=a.category AND ((b.value>a.value) OR (b.value=a.value AND b.gain_cents>a.gain_cents) OR (b.value=a.value AND b.gain_cents=a.gain_cents AND b.trades<a.trades) OR (b.value=a.value AND b.gain_cents=a.gain_cents AND b.trades=a.trades AND b.submitted_at<a.submitted_at) OR (b.value=a.value AND b.gain_cents=a.gain_cents AND b.trades=a.trades AND b.submitted_at=a.submitted_at AND b.tie_id<a.tie_id))))), '[]') FROM sf_leaderboard_top100 a WHERE a.player_id=NEW.player_id AND a.mode=(SELECT mode FROM sf_sessions WHERE id=NEW.session_id) AND a.category='reincarnation') WHERE session_id=NEW.session_id;
UPDATE sf_players SET life_completed_count=life_completed_count+((SELECT mode FROM sf_sessions WHERE id=NEW.session_id)='life'),free_completed_count=free_completed_count+((SELECT mode FROM sf_sessions WHERE id=NEW.session_id)='free'),life_last_completed_at=CASE WHEN (SELECT mode FROM sf_sessions WHERE id=NEW.session_id)='life' THEN MAX(COALESCE(life_last_completed_at,NEW.created_at),NEW.created_at) ELSE life_last_completed_at END,free_last_completed_at=CASE WHEN (SELECT mode FROM sf_sessions WHERE id=NEW.session_id)='free' THEN MAX(COALESCE(free_last_completed_at,NEW.created_at),NEW.created_at) ELSE free_last_completed_at END WHERE id=NEW.player_id;
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id)
 SELECT c.mode,c.category,c.player_id,c.run_id,c.value,c.gain_cents,c.trades,c.submitted_at,c.tie_id FROM (SELECT 'life' mode,'reincarnation' category,p.id player_id,NULL run_id,p.life_completed_count value,0 gain_cents,0 trades,p.life_last_completed_at submitted_at,p.id tie_id FROM sf_players p WHERE p.banned=0 AND p.nickname IS NOT NULL AND p.life_completed_count>0 AND p.id=NEW.player_id AND (SELECT mode FROM sf_sessions WHERE id=NEW.session_id)='life') c
 WHERE (EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id AND ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id)))
 OR (NOT EXISTS(SELECT 1 FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category AND b.player_id=c.player_id)
 AND ((SELECT COUNT(*) FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category)<100
 OR EXISTS(SELECT 1 FROM (SELECT * FROM sf_leaderboard_top100 b WHERE b.mode=c.mode AND b.category=c.category ORDER BY value,gain_cents,trades DESC,submitted_at DESC,tie_id DESC LIMIT 1) b WHERE ((c.value>b.value) OR (c.value=b.value AND c.gain_cents>b.gain_cents) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades<b.trades) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at<b.submitted_at) OR (c.value=b.value AND c.gain_cents=b.gain_cents AND c.trades=b.trades AND c.submitted_at=b.submitted_at AND c.tie_id<b.tie_id))))))
 ON CONFLICT(mode,category,player_id) DO UPDATE SET run_id=excluded.run_id,value=excluded.value,gain_cents=excluded.gain_cents,trades=excluded.trades,submitted_at=excluded.submitted_at,tie_id=excluded.tie_id;
DELETE FROM sf_leaderboard_top100 WHERE mode='life' AND category='reincarnation' AND player_id IN (SELECT player_id FROM sf_leaderboard_top100 WHERE mode='life' AND category='reincarnation' ORDER BY value DESC,gain_cents DESC,trades,submitted_at,tie_id LIMIT -1 OFFSET 100);
INSERT INTO sf_leaderboard_top100(mode,category,player_id,run_id,value,gain_cents,trades,submitted_at,tie_id)
